// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {LiquidityPool} from "../src/LiquidityPool.sol";

contract InvMutTest is Test {
    LiquidityPool c;
    uint256 constant THRESHOLD = 1e18;

    function setUp() public { c = new LiquidityPool(0, bytes16(0), address(this), address(new __InvMutHandleStub()), address(new __InvMutHandleStub())); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        // The stub share returns (amount > THRESHOLD) from transferFrom for the
        // calldata c forwards. The rule: c.transferFrom must return exactly
        // that boolean. The mutant always returns true, which is wrong when
        // amount <= THRESHOLD (stub reports false).
        vm.prank(actor);
        bool got = c.transferFrom(actor, address(this), amount);
        assertTrue(got == (amount > THRESHOLD));
    }
}

contract __InvMutHandleStub {
    function factory() external view returns (address) { return address(this); }
    function createPair(address, address) external view returns (address) { return address(this); }
    function underlying() external view returns (address) { return address(this); }
    function WETH() external view returns (address) { return address(this); }
    function name() external pure returns (string memory) { return "S"; }
    function symbol() external pure returns (string memory) { return "S"; }
    function decimals() external pure returns (uint8) { return 18; }
    function totalSupply() external pure returns (uint256) { return 0; }
    function balanceOf(address) external pure returns (uint256) { return 0; }
    function allowance(address, address) external view returns (uint256) { return 0; }
    function approve(address, uint256) external view returns (bool) { return true; }
    function transfer(address, uint256) external view returns (bool) { return true; }
    function transferFrom(address, address, uint256 value) external view returns (bool) { return value > 1e18; }
    receive() external payable {}
    fallback() external payable {}
}
